// Returns the next character, or raises "unterminated string" (at the
// literal's opening quote) when the input has run out.
function requireChar(cursor, startLine, startCol) {
  if (cursor.atEnd()) throw new LexError(startLine, startCol, 'unterminated string')
  return cursor.peek()
}

