  const startLine = cursor.line
  const startCol = cursor.col
  cursor.advance() // opening quote
  let value = ''

  for (;;) {
    const c = requireChar(cursor, startLine, startCol)
    if (c === '"') {
      cursor.advance()
      break
    }
    if (c === '\n') throw new LexError(cursor.line, cursor.col, 'newline in string')
    if (c === '\\') {
