      const escCol = cursor.col
      cursor.advance()
      const e = requireChar(cursor, startLine, startCol)
      cursor.advance()
      value += decodeEscape(cursor, e, escLine, escCol, startLine, startCol)
      continue
    }
    value += c
    cursor.advance()
  }

  return { kind: 'string', text: value, line: startLine, col: startCol }
}

