  switch (e) {
    case 'n':
      return '\n'
    case 't':
      return '\t'
    case 'r':
      return '\r'
    case '\\':
      return '\\'
    case '"':
      return '"'
    case '0':
      return '\0'
    case 'x':
      return decodeHexByte(cursor, escLine, escCol, startLine, startCol)
    case 'u':
      return decodeUnicodeEscape(cursor, escLine, escCol, startLine, startCol)
    default:
      throw new LexError(escLine, escCol, `invalid escape \\${e}`)
  }
