  const h1 = requireChar(cursor, startLine, startCol)
  if (!isHexDigit(h1)) throw new LexError(escLine, escCol, 'invalid escape \\x')
  cursor.advance()
  const h2 = requireChar(cursor, startLine, startCol)
  if (!isHexDigit(h2)) throw new LexError(escLine, escCol, 'invalid escape \\x')
  cursor.advance()
  return String.fromCharCode(parseInt(h1 + h2, 16))
