  const open = requireChar(cursor, startLine, startCol)
  if (open !== '{') throw new LexError(escLine, escCol, 'invalid escape \\u')
  cursor.advance()

  let hex = ''
  for (;;) {
    const hc = requireChar(cursor, startLine, startCol)
    if (!isHexDigit(hc)) break
